// The committed icons in icons/ match the design in src/core/app-icon.js
// (openspec/changes/add-pwa-install/specs/app-install/spec.md: "The app icon is a cross-stitched
// heart", "Icons are generated by a dependency-free script"). Pixels are compared, not file
// bytes, because compressed bytes may differ between Node versions.
// After changing the design, run: node scripts/make-icons.js

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { renderIcon, iconSvg } from '../../src/core/app-icon.js';
import { readPngHeader } from '../../src/core/png.js';
import { PNG_ICONS, SVG_ICON_FILE } from '../../scripts/make-icons.js';
import { decodePngPixels } from '../helpers/png-pixels.js';

const ICONS_DIRECTORY = new URL('../../icons/', import.meta.url);
const REGENERATE_HINT = 'run node scripts/make-icons.js';

async function readIcon(file) {
  return new Uint8Array(await readFile(new URL(file, ICONS_DIRECTORY)));
}

// The first differing pixel as text, or null when both images are equal.
function firstDifference(actual, expected) {
  for (let index = 0; index < expected.rgb.length; index += 3) {
    for (let channel = 0; channel < 3; channel++) {
      if (actual.rgb[index + channel] !== expected.rgb[index + channel]) {
        const pixel = index / 3;
        return `(${pixel % expected.width}, ${Math.floor(pixel / expected.width)})`;
      }
    }
  }
  return null;
}

describe('committed app icons', () => {
  it('lists the five PNG files of the spec with their sizes', () => {
    assert.deepEqual(
      PNG_ICONS.map(({ file, size }) => `${file} ${size}`),
      ['icon-192.png 192', 'icon-512.png 512', 'icon-maskable-512.png 512', 'apple-touch-icon.png 180', 'favicon-32.png 32'],
    );
  });

  for (const { file, size, layout } of PNG_ICONS) {
    it(`${file} is a ${size} × ${size} 8-bit RGB PNG`, async () => {
      assert.deepEqual(readPngHeader(await readIcon(file)), { width: size, height: size, bitDepth: 8, colorType: 2 });
    });

    it(`${file} has exactly the pixels of renderIcon(${size}, '${layout}')`, async () => {
      const actual = decodePngPixels(await readIcon(file));
      const difference = firstDifference(actual, renderIcon(size, layout));
      assert.equal(difference, null, `icons/${file} differs from the design at ${difference}; ${REGENERATE_HINT}`);
    });
  }

  it(`${SVG_ICON_FILE} equals iconSvg()`, async () => {
    const svg = await readFile(new URL(SVG_ICON_FILE, ICONS_DIRECTORY), 'utf8');
    assert.equal(svg, iconSvg(), `icons/${SVG_ICON_FILE} differs from the design; ${REGENERATE_HINT}`);
  });
});
